<script setup lang="ts">
import { t, messageText, tr } from '@/i18n'
import { onBeforeUnmount, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { useRouter } from 'vue-router'
const emit=defineEmits<{challenge:[string]}>()
const auth=useAuthStore(),router=useRouter(),busy=ref(false),message=ref(''),link=ref(''),code=ref(''),confirmed=ref(false),username=ref('')
const otp=ref('')
let generation=0
let state='',timer:ReturnType<typeof setTimeout>|undefined,expires=0,disposed=false
async function request(path:string,body?:object){const r=await fetch(`/api/v1/auth/social/telegram/deeplink/${path}`,{method:'POST',headers:{'Content-Type':'application/json','X-TOTP-Code':otp.value,'X-Session-Mode':'cookie','X-Acquisition-Source':sessionStorage.getItem('acquisition_source')||''},body:JSON.stringify(body||{})});const d=await r.json();if(d.detail?.code==='MFA_REQUIRED'){emit('challenge',d.detail.challenge);return {mfa_required:true}}if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Вход через бота недоступен');return d}
async function start(){if(busy.value)return;const current=++generation;busy.value=true;message.value='';clearTimeout(timer);confirmed.value=false;username.value='';link.value='';code.value='';state='';otp.value='';try{const d=await request('start');if(disposed||current!==generation)return;state=d.state;link.value=d.url;code.value=d.verification_code;expires=Date.now()+d.expires_in*1000;timer=setTimeout(poll,2000)}catch(e:any){message.value=e.message}finally{busy.value=false}}
async function poll(){if(disposed)return;const current=generation;if(Date.now()>expires){message.value='Ссылка истекла. Начните вход заново.';link.value='';return}try{const d=await request('poll',{state});if(disposed||current!==generation)return;if(d.status==='confirmed'){confirmed.value=true;username.value=d.username||t('пользователь Telegram');return}}catch(e:any){if(current===generation)message.value=e.message;return}timer=setTimeout(poll,2000)}
async function complete(){if(busy.value||!confirmed.value)return;busy.value=true;message.value='';try{const d=await request('complete',{state});if(disposed||d.mfa_required)return;localStorage.removeItem('telegram_require_confirmation');auth.setToken('cookie-session');await auth.fetchCurrentUser();if(!auth.user.value)throw new Error('Не удалось проверить сессию');await router.push('/')}catch(e:any){message.value=e.message}finally{busy.value=false}}
onBeforeUnmount(()=>{disposed=true;generation++;clearTimeout(timer);state=''})
</script>
<template><section class="bot-login" :aria-label="tr('Новый вход через Telegram','New Telegram sign-in')"><p>{{tr('Выберите нужный аккаунт в приложении Telegram, затем откройте бота и подтвердите новый вход. Старое разрешение виджета не используется.','Select the account in your Telegram app, then open the bot and confirm a new sign-in. The widget’s previous permission is not used.')}}</p><button type="button" @click="start" :disabled="busy">{{link?t("Начать вход заново"):t("Войти через Telegram-бота")}}</button><template v-if="link"><p>{{ t("Код проверки:") }} <strong>{{code}}</strong>{{ t(". Откройте бота, сравните код и подтвердите вход. Не пересылайте ссылку.") }}</p><a :href="link" target="_blank" rel="noopener noreferrer">{{ t("Открыть бота") }}</a><label v-if="confirmed">{{t('Код 2FA или резервный код')}}<input v-model="otp" autocomplete="one-time-code" maxlength="64" /></label><button v-if="confirmed" type="button" @click="complete" :disabled="busy">{{ t("Войти как") }} {{username}}</button><p v-else role="status">{{ t("Ожидается подтверждение в Telegram…") }}</p></template><p v-if="message" role="alert">{{messageText(message)}}</p></section></template>
<style scoped>.bot-login{display:grid;gap:12px;text-align:center;max-width:420px}.bot-login button,.bot-login a{padding:12px;border:1px solid #596780;border-radius:8px;background:#27324a;color:#fff;font:inherit}.bot-login p{font-size:14px;line-height:1.5}.bot-login [role=alert]{color:#fca5a5}</style>
